function editContact(t){const e=document.getElementById("contact-value-"+t),n=e.textContent,a=document.createElement("input");a.type="text",a.value=n,a.className="w-full px-3 py-2 text-sm bg-rose-800/50 border border-rose-500/30 rounded-lg text-slate-900 focus:outline-none focus:border-rose-500",a.id="contact-input-"+t,a.addEventListener("blur",function(){saveContact(t,this.value)}),a.addEventListener("keypress",function(e){"Enter"===e.key&&saveContact(t,this.value)}),e.replaceWith(a),a.focus()}async function saveContact(t,e){const n=document.getElementById("contact-input-"+t),a=document.createElement("p");a.className="text-slate-400 text-sm break-all",a.id="contact-value-"+t,a.textContent=e;try{const c=await fetch("/api/contacts/"+t,{method:"PUT",headers:{"Content-Type":"application/json","X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({value:e})});(await c.json()).success||(alert("Gagal menyimpan perubahan"),a.textContent=n.value),n.replaceWith(a)}catch(t){alert("Terjadi kesalahan"),a.textContent=n.value,n.replaceWith(a)}}